import { z } from "zod";
const zLinkProps = z.object({
    label: z.string().optional(),
    href: z.string(),
    target: z.string().optional(),
    download: z.union([z.boolean(), z.string()]).optional(),
    icon: z.string().optional(),
    appearance: z
        .enum([
        "link",
        "button",
        "button_outline",
        "button_secondary",
        "button_muted",
    ])
        .default("link")
        .optional(),
});
export function Link(define) {
    return define("Link")
        .props(zLinkProps)
        .userEvents({
        click: [z.literal(true), false],
    })
        .render((props) => ({
        label: props.label,
        icon: props.icon,
        href: props.href,
        target: props.target,
        download: props.download,
        appearance: props.appearance,
    }));
}
